INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4956503, 721508, 74911, '<td valign="top">I liked this one a lot... the way my eye travels from the person to the number on top and then to the doors and back to the person is an evidence of a very impressive composition. And the dashing red colors gives a punch. Very good one.</td>', 'I liked this one a lot... the way my eye travels from the person to the number on top and then to the doors and back to the person is an evidence of a very impressive composition. And the dashing red colors gives a punch. Very good one.', '2008-09-15 15:21:00.000000', NULL, 1),
(4956505, 721246, 74911, '<td valign="top">Very nice composition and usage of perspective. Hope this does well.</td>', 'Very nice composition and usage of perspective. Hope this does well.', '2008-09-15 15:21:38.000000', NULL, 1),
(4956506, 721514, 74911, '<td valign="top">Amazing elements of design... very nice composition... the tilt adds interest... very nice colors too... Hope to see in the first page...</td>', 'Amazing elements of design... very nice composition... the tilt adds interest... very nice colors too... Hope to see in the first page...', '2008-09-15 15:22:54.000000', NULL, 1),
(4956508, 719800, 74911, '<td valign="top">My fav in this challenge... this would definitely do well in this challenge... Though the red colored umbrella goes with the red spot on the road, why is she holding the umbrella? It doesn''t seem to be like it is raining. Other than that it has all chances of being on top 5 or even a ribbon. Good luck!</td>', 'My fav in this challenge... this would definitely do well in this challenge... Though the red colored umbrella goes with the red spot on the road, why is she holding the umbrella? It doesn''t seem to be like it is raining. Other than that it has all chances of being on top 5 or even a ribbon. Good luck!', '2008-09-15 15:25:15.000000', NULL, 1),
(4956509, 721643, 74911, '<td valign="top">Very nice concept. A bit literal to meet the challenge. But the way you replaced E with 3 makes it.</td>', 'Very nice concept. A bit literal to meet the challenge. But the way you replaced E with 3 makes it.', '2008-09-15 15:25:53.000000', NULL, 1),
(4956510, 721297, 74911, '<td valign="top">Very funny... :)</td>', 'Very funny... :)', '2008-09-15 15:26:03.000000', NULL, 1),
(4956511, 721650, 74911, '<td valign="top">Very clever use of selective desaturation. I like how you wisely used this with number challenge. Hope this is on the first page.</td>', 'Very clever use of selective desaturation. I like how you wisely used this with number challenge. Hope this is on the first page.', '2008-09-15 15:27:25.000000', NULL, 1),
(4956531, 720895, 3102, '<td valign="top">One of my more bizarre voting habits is to occasionally try to figure out where shots were taken based on a few clues.  I had some fun looking this one up.  The route signs appear to be from PA (since I''m in PA, I could recognize that)... so I did some looking and am guessing this is in Montgomeryville?  Cool clouds :)</td>', 'One of my more bizarre voting habits is to occasionally try to figure out where shots were taken based on a few clues.  I had some fun looking this one up.  The route signs appear to be from PA (since I''m in PA, I could recognize that)... so I did some looking and am guessing this is in Montgomeryville?  Cool clouds :)', '2008-09-15 15:35:15.000000', NULL, 1),
(4956571, 720963, 28742, '<td valign="top">And yet you never called. :(</td>', 'And yet you never called. :(', '2008-09-15 15:47:27.000000', NULL, 1),
(4956586, 721613, 73250, '<td valign="top">Beautiful image...the perspective works and the colors are amazing. I love everything about the this...I can see it hanging on a wall. Only, you really shoehorned it...I can''t even read the numbers. I''m not going to score this. Had you put this in the free study...you would have gotten a 9 or 10 from me.</td>', 'Beautiful image...the perspective works and the colors are amazing. I love everything about the this...I can see it hanging on a wall. Only, you really shoehorned it...I can''t even read the numbers. I''m not going to score this. Had you put this in the free study...you would have gotten a 9 or 10 from me.', '2008-09-15 15:52:23.000000', NULL, 1),
(4956592, 721337, 73250, '<td valign="top">Well seen...this one made me giggle!</td>', 'Well seen...this one made me giggle!', '2008-09-15 15:53:44.000000', NULL, 1),
(4956642, 720813, 9510, '<td valign="top">Very cool. Captures the contest theme and is a very unique image.</td>', 'Very cool. Captures the contest theme and is a very unique image.', '2008-09-15 16:11:34.000000', NULL, 1),
