(4961868, 721553, 97811, '<td valign="top">love the beans! very interesting image....</td>', 'love the beans! very interesting image....', '2008-09-18 14:39:34.000000', NULL, 1),
(4961882, 721502, 83313, '<td valign="top">Seems a touch grainy, but otherwise very good. Well done lighting and an interesting approach to highlight the number.</td>', 'Seems a touch grainy, but otherwise very good. Well done lighting and an interesting approach to highlight the number.', '2008-09-18 14:45:20.000000', NULL, 1),
(4961885, 721663, 83313, '<td valign="top">This is a tough one, as it''s really a portrait of this man and the number is incidental rather than being the subject. I won''t ding it.</td>', 'This is a tough one, as it''s really a portrait of this man and the number is incidental rather than being the subject. I won''t ding it.', '2008-09-18 14:47:04.000000', NULL, 1),
(4961894, 721254, 83313, '<td valign="top">Not sure what the relation is to the theme of numbers, but I think it is a case of this one just going over my head. Very nicely lit and pleasing details.</td>', 'Not sure what the relation is to the theme of numbers, but I think it is a case of this one just going over my head. Very nicely lit and pleasing details.', '2008-09-18 14:49:56.000000', NULL, 1),
(4961898, 721523, 83313, '<td valign="top">Nice grungy look to this.</td>', 'Nice grungy look to this.', '2008-09-18 14:50:44.000000', NULL, 1),
(4961901, 721304, 83313, '<td valign="top">Sleeping in always feels best when you know you really need to be getting up!</td>', 'Sleeping in always feels best when you know you really need to be getting up!', '2008-09-18 14:51:45.000000', NULL, 1),
(4961911, 721570, 83313, '<td valign="top">I like it, though I do find the comp tends to lead my eye toward the out of focus area.</td>', 'I like it, though I do find the comp tends to lead my eye toward the out of focus area.', '2008-09-18 14:55:06.000000', NULL, 1),
(4961919, 721587, 83313, '<td valign="top">Nice lighting and details on the viewer, the background kind of loses me a bit.</td>', 'Nice lighting and details on the viewer, the background kind of loses me a bit.', '2008-09-18 14:57:48.000000', NULL, 1),
(4961923, 721266, 83313, '<td valign="top">Makes me both sad and angry.</td>', 'Makes me both sad and angry.', '2008-09-18 14:58:53.000000', NULL, 1),
(4961925, 721572, 83313, '<td valign="top">An excellent reminder of something that should not be forgotten.</td>', 'An excellent reminder of something that should not be forgotten.', '2008-09-18 14:59:31.000000', NULL, 1),
(4961927, 721598, 83313, '<td valign="top">Kind of plain, I''m afraid, and the hard shadows don''t do anything for it.</td>', 'Kind of plain, I''m afraid, and the hard shadows don''t do anything for it.', '2008-09-18 15:00:34.000000', NULL, 1),
(4961931, 721353, 83313, '<td valign="top">I might have straightened out the curved building for more impact, but thats a personal creative choice, not really a criticism.</td>', 'I might have straightened out the curved building for more impact, but thats a personal creative choice, not really a criticism.', '2008-09-18 15:01:54.000000', NULL, 1),
(4961934, 721658, 83313, '<td valign="top">Just not grabbing me at all, but I can''t identify why.</td>', 'Just not grabbing me at all, but I can''t identify why.', '2008-09-18 15:03:48.000000', NULL, 1),
(4961942, 721190, 83313, '<td valign="top">This could be my Dad''s boat, it has my mom''s name on it. I''m afraid this comes off to me almost as a snapshot.</td>', 'This could be my Dad''s boat, it has my mom''s name on it. I''m afraid this comes off to me almost as a snapshot.', '2008-09-18 15:06:02.000000', NULL, 1),
(4961946, 721508, 83313, '<td valign="top">Is she proud of that size?</td>', 'Is she proud of that size?', '2008-09-18 15:07:00.000000', NULL, 1),
(4961952, 721233, 83313, '<td valign="top">Nice colors and sharpness, though the composition strikes me a little odd.</td>', 'Nice colors and sharpness, though the composition strikes me a little odd.', '2008-09-18 15:09:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4962096, 721350, 83845, '<td valign="top">Very creative.  Love the title.  Great lighting!</td>', 'Very creative.  Love the title.  Great lighting!', '2008-09-18 16:19:29.000000', NULL, 1),
(4962101, 721229, 83845, '<td valign="top">very well composed and nice lighting.</td>', 'very well composed and nice lighting.', '2008-09-18 16:21:00.000000', NULL, 1),
(4962113, 721592, 83845, '<td valign="top">Uhg.  Should have expected this when voting on numbers challenge.  I work in a college math department and see this all day long.  Great depth of field.  Overall a great shot and fits the challenge more than most so far.</td>', 'Uhg.  Should have expected this when voting on numbers challenge.  I work in a college math department and see this all day long.  Great depth of field.  Overall a great shot and fits the challenge more than most so far.', '2008-09-18 16:23:52.000000', NULL, 1),
(4962358, 721592, 49954, '<td valign="top">Nice work... love the DOF</td>', 'Nice work... love the DOF', '2008-09-18 18:25:24.000000', NULL, 1),
(4962359, 721580, 49954, '<td valign="top">Sweet!</td>', 'Sweet!', '2008-09-18 18:25:58.000000', NULL, 1),
(4962362, 721538, 49954, '<td valign="top">I think it might have worked better showing the other side (the two) instead of the five.  It would have made the 1 stand out more against the "couples".  Nicely done though.  Dice shots rock :)</td>', 'I think it might have worked better showing the other side (the two) instead of the five.  It would have made the 1 stand out more against the "couples".  Nicely done though.  Dice shots rock :)', '2008-09-18 18:26:58.000000', NULL, 1),
(4962365, 721310, 49954, '<td valign="top">You took the rings off??</td>', 'You took the rings off??', '2008-09-18 18:28:08.000000', NULL, 1),
