(4963910, 719800, 97893, '<td valign="top">Wonderful image! I am wondering if the Hopscotch was created just to shoot for the challenge :-). Fits the theme, very nice and gets the attention of viewers in composition, color use, texture etc.</td>', 'Wonderful image! I am wondering if the Hopscotch was created just to shoot for the challenge :-). Fits the theme, very nice and gets the attention of viewers in composition, color use, texture etc.', '2008-09-19 10:51:48.000000', NULL, 1),
(4963914, 721521, 97893, '<td valign="top">Very nice! I am sure you had loads of  fun doing it.:-)</td>', 'Very nice! I am sure you had loads of  fun doing it.:-)', '2008-09-19 10:52:56.000000', NULL, 1),
(4963915, 721653, 97893, '<td valign="top">Nice idea presented in this picture!</td>', 'Nice idea presented in this picture!', '2008-09-19 10:54:05.000000', NULL, 1),
(4963977, 719800, 98707, '<td valign="top">I was just thinking how, even though it quite popular, it''s actually difficult to get a photograph to look good with the b&amp;w AND color technique. But this is perfect.</td>', 'I was just thinking how, even though it quite popular, it''s actually difficult to get a photograph to look good with the b&w AND color technique. But this is perfect.', '2008-09-19 11:49:21.000000', NULL, 1),
(4964112, 721508, 58792, '<td valign="top">Love composition, strong colors and even font of numbers. great.</td>', 'Love composition, strong colors and even font of numbers. great.', '2008-09-19 12:57:21.000000', NULL, 1),
(4964378, 719800, 79681, '<td valign="top">I like the red accents</td>', 'I like the red accents', '2008-09-19 15:03:18.000000', NULL, 1),
