(4967303, 720719, 94265, '<td valign="top">Composition is a bit scattered but it''s a cool idea. No glare on the metal either, well done.</td>', 'Composition is a bit scattered but it''s a cool idea. No glare on the metal either, well done.', '2008-09-21 23:59:18.000000', NULL, 1),
(4967305, 721661, 94265, '<td valign="top">The dart seems a wee bit more the focus of the shot than the numbers but I love the dartboard idea. I quite like the b&amp;w border.</td>', 'The dart seems a wee bit more the focus of the shot than the numbers but I love the dartboard idea. I quite like the b&w border.', '2008-09-22 00:00:44.000000', NULL, 1),
(4967306, 721619, 94265, '<td valign="top">Interesting angle, light is a tad flat.</td>', 'Interesting angle, light is a tad flat.', '2008-09-22 00:01:02.000000', NULL, 1),
(4967307, 721190, 94265, '<td valign="top">I''m not keen on that blown out sky but there''s something nicely sentimental about this old well-worn boat.</td>', 'I''m not keen on that blown out sky but there''s something nicely sentimental about this old well-worn boat.', '2008-09-22 00:02:04.000000', NULL, 1),
(4967310, 721587, 94265, '<td valign="top">Little tight on the crop at the bottom but the focus on the binocular machine is really good and clear. I like the positioning too.</td>', 'Little tight on the crop at the bottom but the focus on the binocular machine is really good and clear. I like the positioning too.', '2008-09-22 00:03:07.000000', NULL, 1),
(4967311, 720602, 94265, '<td valign="top">The focus seems to be on the word Lamborghini rather than any numbers but I kinda like that transparant border.</td>', 'The focus seems to be on the word Lamborghini rather than any numbers but I kinda like that transparant border.', '2008-09-22 00:04:41.000000', NULL, 1),
(4967312, 720590, 94265, '<td valign="top">Overprocessed I think and as for fitting the challenge, I think you''re reaching a bit. Pretty colours on the iris.</td>', 'Overprocessed I think and as for fitting the challenge, I think you''re reaching a bit. Pretty colours on the iris.', '2008-09-22 00:05:37.000000', NULL, 1),
(4967314, 719567, 94265, '<td valign="top">I''m confused haha, some weird kind of calculus? I suck at maths :) The focus on the green pen is really good, I think I''d have positioned them a bit differently though.</td>', 'I''m confused haha, some weird kind of calculus? I suck at maths :) The focus on the green pen is really good, I think I''d have positioned them a bit differently though.', '2008-09-22 00:06:49.000000', NULL, 1),
(4967315, 721236, 94265, '<td valign="top">Nice complimentary colours, I find that abandoned magazine a bit distracting though.</td>', 'Nice complimentary colours, I find that abandoned magazine a bit distracting though.', '2008-09-22 00:07:50.000000', NULL, 1),
(4967316, 721647, 94265, '<td valign="top">It''s very dark on the horse''s face, all of the horse in fact but it does help emphasise the white numbers. I think I''d have bent down those 3 grass stalks out of the way a bit.</td>', 'It''s very dark on the horse''s face, all of the horse in fact but it does help emphasise the white numbers. I think I''d have bent down those 3 grass stalks out of the way a bit.', '2008-09-22 00:09:16.000000', NULL, 1),
(4967317, 721274, 94265, '<td valign="top">Good crop and focus.</td>', 'Good crop and focus.', '2008-09-22 00:09:35.000000', NULL, 1),
(4967319, 719570, 94265, '<td valign="top">I''m not hugely keen on that blank blue taking over the photo but the title is pretty amusing, maybe you could''ve zoned in on the number 20 there a bit?</td>', 'I''m not hugely keen on that blank blue taking over the photo but the title is pretty amusing, maybe you could''ve zoned in on the number 20 there a bit?', '2008-09-22 00:10:34.000000', NULL, 1),
(4967320, 721581, 94265, '<td valign="top">The colour is good but I''d have kept the border even all the way around.</td>', 'The colour is good but I''d have kept the border even all the way around.', '2008-09-22 00:11:21.000000', NULL, 1),
(4967321, 721463, 94265, '<td valign="top">Focus on the cards is superb, even if they''re not numbered.</td>', 'Focus on the cards is superb, even if they''re not numbered.', '2008-09-22 00:12:11.000000', NULL, 1),
(4967322, 721526, 94265, '<td valign="top">Nice colours and composition, not sure why you''ve desaturated three cones and not the last one though?</td>', 'Nice colours and composition, not sure why you''ve desaturated three cones and not the last one though?', '2008-09-22 00:13:33.000000', NULL, 1),
(4967325, 721517, 94265, '<td valign="top">I think I''d have backed off a bit to get more of the cafe in, as it seems to be a pleasant traditional looking place, judging by the menu board and the flowers on the sill. Nothing really wrong with the shot/crop as you have it, I''d just find a shot of the cafe front more appealing with focus on the menu board.</td>', 'I think I''d have backed off a bit to get more of the cafe in, as it seems to be a pleasant traditional looking place, judging by the menu board and the flowers on the sill. Nothing really wrong with the shot/crop as you have it, I''d just find a shot of the cafe front more appealing with focus on the menu board.', '2008-09-22 00:15:17.000000', NULL, 1),
(4967326, 721513, 94265, '<td valign="top">Not keen on those dark shadows but this made me think of my first sums in primary school; extra point for evoking a memory with your shot. :)</td>', 'Not keen on those dark shadows but this made me think of my first sums in primary school; extra point for evoking a memory with your shot. :)', '2008-09-22 00:16:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4967328, 721595, 94265, '<td valign="top">Good crop and focus, the green stands out nicely.</td>', 'Good crop and focus, the green stands out nicely.', '2008-09-22 00:17:00.000000', NULL, 1),
(4967329, 721658, 94265, '<td valign="top">I think I see a person through the glass, which is a wee bit distracting but the numbers are nice and clear, I like the crop.</td>', 'I think I see a person through the glass, which is a wee bit distracting but the numbers are nice and clear, I like the crop.', '2008-09-22 00:17:53.000000', NULL, 1),
