(4967334, 721553, 94265, '<td valign="top">The peapods look a bit grainy but the black whatever-it-is is in really good focus. Actually, I''m not sure what the purpose of the peas'' presence but they don''t bother me.</td>', 'The peapods look a bit grainy but the black whatever-it-is is in really good focus. Actually, I''m not sure what the purpose of the peas'' presence but they don''t bother me.', '2008-09-22 00:20:20.000000', NULL, 1),
(4967335, 721502, 94265, '<td valign="top">Good composition and crop, looks just a wee bit grainy though, perhaps from compression.</td>', 'Good composition and crop, looks just a wee bit grainy though, perhaps from compression.', '2008-09-22 00:21:27.000000', NULL, 1),
(4967340, 721074, 94265, '<td valign="top">The referee looks a bit intimidated! Good capture of motion and plenty of numbers visible.</td>', 'The referee looks a bit intimidated! Good capture of motion and plenty of numbers visible.', '2008-09-22 00:23:13.000000', NULL, 1),
(4967347, 721336, 96614, '<td valign="top">Nice DOF!!!</td>', 'Nice DOF!!!', '2008-09-22 00:27:29.000000', NULL, 1),
(4967348, 721592, 96614, '<td valign="top">Nice DOF!!!</td>', 'Nice DOF!!!', '2008-09-22 00:27:45.000000', NULL, 1),
